as for the hp, if thats the only place you want that to happen in, then try saving this as a .js file and adding it to your project as a plugin
Code:
Window_BattleEnemy.prototype.drawItem = function(index) {
    this.resetTextColor();
    const name = this._enemies[index].name();
    const rect = this.itemLineRect(index);
    if (this._enemies[index].hpRate()<.5)
        this.changeTextColor("#ffff40");
    if (this._enemies[index].hpRate()<.25)
        this.changeTextColor("#ff2020");
    this.drawText(name, rect.x, rect.y, rect.width);
    this.resetTextColor()
};

